BEGIN;
CREATE TEMP TABLE _enr(rid text,addr1 text,addr2 text,city text,state text,zip text,county text,website text,phone text,phone_raw text,contact text,fname text,lname text,email text,note text) ON COMMIT DROP;
UPDATE accounts a SET
 address_line_1=COALESCE(NULLIF(t.addr1,''),a.address_line_1),
 city=COALESCE(NULLIF(t.city,''),a.city),
 state=COALESCE(NULLIF(t.state,''),a.state),
 zip=COALESCE(NULLIF(t.zip,''),a.zip),
 county=COALESCE(NULLIF(t.county,''),a.county),
 website=COALESCE(NULLIF(t.website,''),a.website),
 phone=COALESCE(NULLIF(a.phone,''),NULLIF(t.phone,'')),
 phone_raw=COALESCE(NULLIF(a.phone_raw,''),NULLIF(t.phone_raw,'')),
 notes=CASE WHEN NULLIF(t.note,'') IS NOT NULL THEN COALESCE(a.notes||E'\n','')||t.note ELSE a.notes END,
 updated_at=now()
FROM _enr t WHERE a.filta_record_id=t.rid AND a.deleted_at IS NULL;
UPDATE contacts c SET
 email=COALESCE(NULLIF(c.email,''),NULLIF(t.email,'')),
 full_name=COALESCE(NULLIF(c.full_name,''),NULLIF(t.contact,'')),
 first_name=COALESCE(NULLIF(c.first_name,''),NULLIF(t.fname,'')),
 last_name=COALESCE(NULLIF(c.last_name,''),NULLIF(t.lname,'')),
 updated_at=now()
FROM _enr t JOIN accounts a ON a.filta_record_id=t.rid AND a.deleted_at IS NULL
WHERE c.account_id=a.id AND c.is_primary=true AND c.deleted_at IS NULL;
SELECT DISTINCT ON (a.id) gen_random_uuid(), a.id, NULLIF(t.fname,''), NULLIF(t.lname,''), NULLIF(t.contact,''), NULLIF(t.email,''), true, now(), now()
FROM _enr t JOIN accounts a ON a.filta_record_id=t.rid AND a.deleted_at IS NULL
WHERE (NULLIF(t.contact,'') IS NOT NULL OR NULLIF(t.email,'') IS NOT NULL)
AND NOT EXISTS(SELECT 1 FROM contacts c WHERE c.account_id=a.id AND c.is_primary=true AND c.deleted_at IS NULL)
ORDER BY a.id;
\echo === RESULTS ===
SELECT count(*) AS enr_rows FROM _enr;
SELECT count(*) AS matched_accounts FROM _enr t WHERE EXISTS(SELECT 1 FROM accounts a WHERE a.filta_record_id=t.rid AND a.deleted_at IS NULL);
SELECT count(*) AS unmatched FROM _enr t WHERE NOT EXISTS(SELECT 1 FROM accounts a WHERE a.filta_record_id=t.rid AND a.deleted_at IS NULL);
SELECT count(*) AS accts_with_addr FROM accounts a JOIN _enr t ON a.filta_record_id=t.rid WHERE a.address_line_1 IS NOT NULL AND a.address_line_1<>'';
SELECT count(*) AS primary_contacts FROM contacts c JOIN accounts a ON c.account_id=a.id JOIN _enr t ON a.filta_record_id=t.rid WHERE c.is_primary AND c.deleted_at IS NULL;
COMMIT;
